                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"reason\":\"供应商召回通知 RC-2026-01\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.quarantinedCount").value(1))
